// The card catalogue, typed. The data is generated by tools/export-cards.py into cards.json;
// what each effect means is explained in docs/game-rules.md (section 9).
import data from './cards.json';

export type CardId = number;

export type CardCategory =
  | 'wall'        // Wall Sections 29-44: built for miles
  | 'manhour'     // Man Hour: pays for a build
  | 'reaction'    // Savings, Self Defense: only used in response to an attack
  | 'immediate'   // must be played as soon as it is in the current player's hand
  | 'action'      // played on your own turn
  | 'placeholder'; // card 4: has a picture but is not in the deck

/** Who a card's effect picks. */
export type Target = 'chosenOpponent' | 'chosenOpponentSet' | 'opponentWall' | 'self';

/** Built walls that can be taken, given away or pulled back: not in a set of 3, not Train-guarded. */
export type WallEligibility = 'notInSetOrGuarded';

export type Effect =
  | { kind: 'wallSection'; miles: [number, number, number] }
  | { kind: 'buildPayment' }
  | { kind: 'buildFree'; max: number }
  | { kind: 'buildSets'; firstSetFree: boolean; extraSetCost: number }
  | { kind: 'draw'; count: number }
  | { kind: 'guardPair' }
  | { kind: 'choice'; options: Effect[][] }
  | { kind: 'stealCards'; from: Target; cardIds: CardId[]; max: number }
  | { kind: 'stealRandom'; from: Target; count: number }
  | { kind: 'removeTrainGuard'; from: Target }
  | { kind: 'takeBuiltWall'; from: Target; eligible: WallEligibility; counter: CardId }
  | { kind: 'giveBuiltWall'; from: Target; to: Target; into: 'hand'; eligible: WallEligibility }
  | { kind: 'everyoneReturnsWall'; eligible: WallEligibility; blockablePerPlayer: boolean }
  | { kind: 'discardFromHand'; cardIds: CardId[]; count: number; who: Target }
  | {
      kind: 'distributeHand';
      who: 'self' | 'mostCards';
      cards: 'all' | 'walls' | 'traffic';
      cardIds?: CardId[];
      includeSelf: boolean;
    }
  | { kind: 'giveToLowest'; cardIds: CardId[]; count: number }
  | { kind: 'limitActions'; target: Target; actions: number; when: 'nextTurn' }
  | { kind: 'skipTurn'; target: Target; afterDrawing: boolean }
  | {
      kind: 'pickFromPiles';
      piles: ('draw' | 'discard')[];
      count: number;
      seconds: number;
      to: 'hand' | 'jail';
      jailTurnsPerPlayer?: number;
      shuffleDrawAfter: boolean;
    }
  | { kind: 'payDebt' }
  | { kind: 'blockAttack' }
  | { kind: 'reshuffleDiscard' }
  | { kind: 'everyoneNewHand'; count: number }
  | { kind: 'extraActions'; count: number }
  | { kind: 'swapHands'; with: Target };

export interface PackInfo {
  id: string;
  name: string;
}

export interface CardImages {
  /** Costume name in the old Scratch project. */
  costume: string;
  /** Full card picture (paths are relative to app/public). */
  card: string;
  high: string | null;
  thumb: string | null;
  mini: string | null;
}

export interface Card {
  id: CardId;
  name: string;
  slug: string;
  category: CardCategory;
  /** Actions it costs to play. */
  cost: number;
  /** Copies in the base deck (0 for pack cards and the placeholder). */
  count: number;
  /** Expansion packs that contain this card. */
  packs: { pack: string; copies: number }[];
  playImmediately: boolean;
  /** Self-Defense can block it. */
  blockable: boolean;
  /** When played it doesn't go straight to the discard pile (held as a marker, or jailed). */
  heldUntilResolved: boolean;
  /** Short help text from the game ('' for most cards). */
  help: string;
  /** The two-line explanation shown when a card is explained. */
  explain: string;
  /** Plain-English effect, always present. */
  effect: string;
  effects: Effect[];
  /** The card's page on buildthatwallgame.com. */
  link: string | null;
  image: CardImages;
}

export interface CardCatalogue {
  deckSize: number;
  packs: PackInfo[];
  cards: Card[];
}

export const catalogue = data as unknown as CardCatalogue;
export const cards: readonly Card[] = catalogue.cards;

const byId = new Map(cards.map((c) => [c.id, c]));

export function cardById(id: CardId): Card {
  const card = byId.get(id);
  if (!card) throw new Error('Unknown card id ' + id);
  return card;
}

// Card ids the rules refer to by number
export const CARD = {
  ManHour: 14,
  Debt: 7,
  Savings: 19,
  SelfDefense: 20,
  TrumpTrain: 25,
  Trump: 26,
} as const;

export const isWall = (id: CardId): boolean => id >= 29 && id <= 44;

/** The 107-card base deck as a list of ids (unshuffled). */
export function baseDeck(): CardId[] {
  return cards.flatMap((c) => Array<CardId>(c.count).fill(c.id));
}
